    demands = get_value(instance, ["demands", "demand"], None)

    customers = []
    try:
        if "customers" in instance:
            customers = list(instance["customers"])
        elif "nodes" in instance:
            customers = list(instance["nodes"])
        elif coords is not None:
            customers = list(range(len(coords)))
        elif dist_matrix is not None:
            customers = list(range(len(dist_matrix)))
        elif demands is not None:
            customers = list(range(len(demands)))
    except:
        customers = []

    if depot in customers:
        customers = [c for c in customers if c != depot]

    def demand_of(i):
        if demands is None:
            return 0
        try:
            return demands[i]
        except:
            try:
                return demands.get(i, 0)
            except:
                return 0

    def dist(i, j):
        if dist_matrix is not None:
            try:
                return dist_matrix[i][j]
            except:
                return 0
        if coords is not None:
            try:
                xi, yi = coords[i][0], coords[i][1]
                xj, yj = coords[j][0], coords[j][1]
                dx = xi - xj
                dy = yi - yj
                return (dx * dx + dy * dy) ** 0.5
            except:
                return 0
        return 0

    if capacity is None:
        total = 0
        for c in customers:
            total += demand_of(c)
        capacity = total if total > 0 else 1

    # Deterministic ordering
    if coords is not None:
        try:
            ox, oy = coords[depot][0], coords[depot][1]
            ordered = []
            for c in customers:
                x, y = coords[c][0], coords[c][1]
                ang = 0
                dx = x - ox
                dy = y - oy
                if dx != 0 or dy != 0:
                    ang = dy / (abs(dx) + abs(dy) + 1e-12)
                ordered.append((ang, dx * dx + dy * dy, -demand_of(c), c))
            ordered.sort()
            ordered = [t[3] for t in ordered]
        except:
            ordered = sorted(customers, key=lambda c: (-demand_of(c), c))
    else:
        ordered = sorted(customers, key=lambda c: (-demand_of(c), c))

    unvisited = {}
    for c in customers:
        unvisited[c] = 1

    routes = []

    # Construction: sweep with nearest-feasible extension
    while unvisited:
        seed = None
        best_key = None
        for c in ordered:
            if c in unvisited:
                key = (dist(depot, c), -demand_of(c), c)
                if best_key is None or key < best_key:
                    best_key = key
                    seed = c
        if seed is None:
            break

        route = [seed]
        load = demand_of(seed)
        del unvisited[seed]
        current = seed

        while unvisited:
            best = None
            best_key = None
            for c in ordered:
                if c not in unvisited:
                    continue
                dc = demand_of(c)
                if load + dc > capacity:
                    continue
                key = (dist(current, c), dist(depot, c), -dc, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = c
            if best is None:
                break
            route.append(best)
            load += demand_of(best)
            current = best
            del unvisited[best]

        routes.append(route)

    # Repair missing/duplicated coverage
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if seen.get(c, 0) == 0]
    if missing:
        for c in missing:
            routes.append([c])

    # Remove duplicates if any by keeping first occurrence
    assigned = {}
    repaired = []
    for r in routes:
        nr = []
        for c in r:
            if c not in assigned:
                assigned[c] = 1
                nr.append(c)
        if nr:
            repaired.append(nr)
    routes = repaired

    # Capacity repair: split overloaded routes greedily
    final_routes = []
    for r in routes:
        cur = []
        load = 0
        for c in r:
            dc = demand_of(c)
            if load + dc <= capacity:
                cur.append(c)
                load += dc
            else:
                if cur:
                    final_routes.append(cur)
                cur = [c]
                load = dc
        if cur:
            final_routes.append(cur)

    # Local improvement: 2-opt within routes for geometry only (kept conservative)
    if coords is not None or dist_matrix is not None:
        improved_routes = []
        for r in final_routes:
            if len(r) <= 3:
                improved_routes.append(r)
                continue
            improved = True
            best_route = r[:]
            while improved:
                improved = False
                n = len(best_route)
                best_delta = 0
                best_i = -1
                best_j = -1
                for i in range(n - 1):
                    a = depot if i == 0 else best_route[i - 1]
                    b = best_route[i]
                    for j in range(i + 1, n):
                        c = best_route[j]
                        d = depot if j == n - 1 else best_route[j + 1]
                        delta = (dist(a, c) + dist(b, d)) - (dist(a, b) + dist(c, d))
                        if delta < best_delta:
                            best_delta = delta
                            best_i = i
                            best_j = j
                if best_i >= 0:
                    best_route = best_route[:best_i] + best_route[best_i:best_j + 1][::-1] + best_route[best_j + 1:]
                    improved = True
            improved_routes.append(best_route)
        final_routes = improved_routes

    # Final exact-once fix
    count = {}
    for r in final_routes:
        for c in r:
            count[c] = count.get(c, 0) + 1

    if customers:
        missing = [c for c in customers if count.get(c, 0) == 0]
        extra = [c for c in count if count[c] > 1]
        if missing or extra:
            pool = {}
            for r in final_routes:
                for idx, c in enumerate(r):
                    pool[c] = pool.get(c, 0) + 1
            final_routes = []
            used = {}
            for c in customers:
                if c not in used:
                    final_routes.append([c])
                    used[c] = 1
            # rebuild greedily from scratch if repair failed
            if len(final_routes) != len(customers):
                final_routes = []
                remaining = {}
                for c in customers:
                    remaining[c] = 1
                while remaining:
                    seed = None
                    best_key = None
                    for c in ordered:
                        if c in remaining:
                            key = (dist(depot, c), -demand_of(c), c)
                            if best_key is None or key < best_key:
                                best_key = key
                                seed = c
                    if seed is None:
                        break
                    route = [seed]
                    load = demand_of(seed)
                    del remaining[seed]
                    current = seed
                    while remaining:
                        best = None
                        best_key = None
                        for c in ordered:
                            if c not in remaining:
                                continue
                            dc = demand_of(c)
                            if load + dc > capacity:
                                continue
                            key = (dist(current, c), dist(depot, c), -dc, c)
                            if best_key is None or key < best_key:
                                best_key = key
                                best = c
                        if best is None:
                            break
                        route.append(best)
                        load += demand_of(best)
                        current = best
                        del remaining[best]
                    final_routes.append(route)

    return final_routes
